const SEED_CHUNKS = [SEED_CHUNK_0, SEED_CHUNK_1, SEED_CHUNK_2, SEED_CHUNK_3, SEED_CHUNK_4, SEED_CHUNK_5, SEED_CHUNK_6, SEED_CHUNK_7];

// ---- Storage helpers ----
async function safeGet(key) {
  try {
    return await window.storage.get(key, false);
  } catch (e) {
    return null;
  }
}
async function safeSet(key, value) {
  try {
    return await window.storage.set(key, value, false);
  } catch (e) {
    return null;
  }
}

async function ensureSeeded() {
  const meta = await safeGet("leadsv2:meta");
  if (meta) {
    try {
      return JSON.parse(meta.value);
    } catch (e) {
      // fall through to reseed
    }
  }
  for (let i = 0; i < SEED_CHUNKS.length; i++) {
    await safeSet(`leadsv2:chunk:${i}`, JSON.stringify(SEED_CHUNKS[i]));
  }
  const metaObj = { chunkCount: SEED_CHUNKS.length, updatedAt: new Date().toISOString(), source: "seed" };
  await safeSet("leadsv2:meta", JSON.stringify(metaObj));
  return metaObj;
}

async function loadAllChunks() {
  const metaObj = await ensureSeeded();
  const { chunkCount, updatedAt } = metaObj;
  let rows = [];
  for (let i = 0; i < chunkCount; i++) {
    const chunk = await safeGet(`leadsv2:chunk:${i}`);
    if (chunk) {
      rows = rows.concat(JSON.parse(chunk.value));
    }
  }
  return { rows, updatedAt };
}

const STATUS_COLORS = {
  booked: "#4ecb8f",
  notBooked: "#e07856",
  unknown: "#8a8478",
};

function normalizeStatus(row) {
  if (row.b === true) return "booked";
  if (row.b === false) return "notBooked";
  return "unknown";
}

function fmtDate(d) {
  if (!d) return "—";
  try {
    const dt = new Date(d);
    if (isNaN(dt.getTime())) return d;
    return dt.toLocaleDateString("en-IN", { day: "2-digit", month: "short", year: "numeric" });
  } catch {
    return d;
  }
}

function fmtDateTime(iso) {
  if (!iso) return "—";
  try {
    const dt = new Date(iso);
    if (isNaN(dt.getTime())) return "—";
    return dt.toLocaleString("en-IN", { day: "2-digit", month: "short", year: "numeric", hour: "2-digit", minute: "2-digit" });
  } catch {
    return "—";
  }
}

function initials(name) {
  if (!name) return "?";
  const parts = name.trim().split(/\s+/);
  return (parts[0]?.[0] || "").toUpperCase() + (parts[1]?.[0] || "").toUpperCase();
}

function isToday(iso) {
  if (!iso) return false;
  const d = new Date(iso);
  const now = new Date();
  return d.toDateString() === now.toDateString();
}

function isTomorrow(iso) {
  if (!iso) return false;
  const d = new Date(iso);
  const t = new Date();
  t.setDate(t.getDate() + 1);
  return d.toDateString() === t.toDateString();
}

